export type IsoStandard =
  | 'ISO/IEC 27001:2022'
  | 'ISO/IEC 27002:2022'
  | 'ISO/IEC 25010'
  | 'ISO/IEC/IEEE 12207'
  | 'ISO/IEC 27701:2025';

export type SignalSeverity = 'critical' | 'warning' | 'info';

export interface StandardSignal {
  id: string;                    // identificador único de la señal
  standard: IsoStandard;         // estándar ISO de origen
  clause?: string;               // cláusula específica (ej: '8.2.1')
  severity: SignalSeverity;
  title: string;                 // descripción corta
  description: string;           // detalle y recomendación
  evidence?: string;             // dato crudo que originó la señal
  remediation?: string;          // cómo resolverlo
  passed: boolean;               // true = cumple, false = no cumple
}

export interface StandardSource {
  getName(): string;
  getStandard(): IsoStandard;
  evaluate(projectRoot: string): Promise<StandardSignal[]>;
}

export interface StandardScore {
  standard: IsoStandard;
  total: number;
  passed: number;
  failed: number;
  warnings: number;
  score: number;                 // 0-100
}

export interface ComplianceReport {
  generatedAt: string;
  projectRoot: string;
  signals: StandardSignal[];
  scores: StandardScore[];
  overallScore: number;          // 0-100
  criticalIssues: StandardSignal[];  // señales con severity=critical y passed=false
}

export class StandardsEngine {
  private sources: StandardSource[] = [];

  addSource(source: StandardSource): void {
    this.sources.push(source);
  }

  async evaluate(projectRoot: string): Promise<ComplianceReport> {
    const allSignals: StandardSignal[] = [];

    for (const source of this.sources) {
      try {
        const signals = await source.evaluate(projectRoot);
        allSignals.push(...signals);
      } catch (error) {
        console.error(`Error evaluating ${source.getName()}:`, error);
      }
    }

    const scores = this.calculateScores(allSignals);
    const overallScore = this.calculateOverallScore(scores);
    const criticalIssues = allSignals.filter(
      s => s.severity === 'critical' && !s.passed
    );

    return {
      generatedAt: new Date().toISOString(),
      projectRoot,
      signals: allSignals,
      scores,
      overallScore,
      criticalIssues,
    };
  }

  private calculateScores(signals: StandardSignal[]): StandardScore[] { ... }
  private calculateOverallScore(scores: StandardScore[]): number { ... }
}

export { StandardsEngine } from './engine';
export type {
  IsoStandard,
  SignalSeverity,
  StandardSignal,
  StandardSource,
  StandardScore,
  ComplianceReport,
} from './types';

